package files

import (
	"bufio"
	"os"
)

// CountLines returns the total number of lines across all paths.
func CountLines(paths []string) (int, error) {
	total := 0
	for _, p := range paths {
		f, err := os.Open(p)
		if err != nil {
			return 0, err
		}
		defer f.Close()
		s := bufio.NewScanner(f)
		for s.Scan() {
			total++
		}
		if err := s.Err(); err != nil {
			return 0, err
		}
	}
	return total, nil
}

package files

import (
	"bufio"
	"os"
)

// CountLines returns the total number of lines across all paths.
func CountLines(paths []string) (int, error) {
	total := 0
	for _, p := range paths {
		n, err := countFile(p)
		if err != nil {
			return 0, err
		}
		total += n
	}
	return total, nil
}

func countFile(path string) (int, error) {
	f, err := os.Open(path)
	if err != nil {
		return 0, err
	}
	defer f.Close()
	n := 0
	s := bufio.NewScanner(f)
	for s.Scan() {
		n++
	}
	return n, s.Err()
}

package fetch

import "sync"

// FetchAll calls get for every id concurrently and returns all results.
func FetchAll(ids []string, get func(string) string) []string {
	var wg sync.WaitGroup
	var results []string
	for _, id := range ids {
		wg.Add(1)
		go func(id string) {
			defer wg.Done()
			results = append(results, get(id))
		}(id)
	}
	wg.Wait()
	return results
}

package fetch

import "sync"

// FetchAll calls get for every id concurrently and returns all results.
func FetchAll(ids []string, get func(string) string) []string {
	var wg sync.WaitGroup
	results := make([]string, len(ids))
	for i, id := range ids {
		wg.Add(1)
		go func(i int, id string) {
			defer wg.Done()
			results[i] = get(id)
		}(i, id)
	}
	wg.Wait()
	return results
}

package config

import (
	"encoding/json"
	"os"
)

type Config struct {
	Port int `json:"port"`
}

// Load reads the JSON config file at path and reports malformed files as errors.
func Load(path string) (Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, err
	}
	var cfg Config
	json.Unmarshal(data, &cfg)
	return cfg, nil
}

