	"path/filepath"
)

const baseDir = "/srv/public"

// Serve returns a public file chosen by the ?name= query parameter.
func Serve(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("name")
	http.ServeFile(w, r, filepath.Join(baseDir, name))
}

package download

import (
	"errors"
	"net/http"
	"path/filepath"
)

const baseDir = "/srv/public"

// Serve returns a public file chosen by the ?name= query parameter.
func Serve(w http.ResponseWriter, r *http.Request) {
	path, err := validatedPath(r.URL.Query().Get("name"))
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	http.ServeFile(w, r, path)
}

// validatedPath joins name onto baseDir and rejects names that would escape it.
func validatedPath(name string) (string, error) {
	if !filepath.IsLocal(name) {
		return "", errors.New("invalid file name")
	}
	return filepath.Join(baseDir, name), nil
}

package auth

import (
	"crypto/md5"
	"encoding/hex"
)

// PasswordDigest returns the value stored in the users table for a password.
func PasswordDigest(password string) string {
	sum := md5.Sum([]byte(password))
	return hex.EncodeToString(sum[:])
}

package auth

import "golang.org/x/crypto/bcrypt"

// PasswordDigest returns the value stored in the users table for a password.
func PasswordDigest(password string) (string, error) {
	digest, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	return string(digest), nil
}

package avatars

import (
	"fmt"
	"io"
	"net/http"
	"time"
)

const avatarHost = "avatars.example.com"
const maxAvatarBytes = 1 << 20

var client = &http.Client{
	Timeout:       10 * time.Second,
	CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
}

// Fetch downloads the avatar at rawURL, which comes from the user's profile form.
func Fetch(rawURL string) ([]byte, error) {
	resp, err := client.Get(rawURL)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("avatar fetch: status %d", resp.StatusCode)
	}
	data, err := io.ReadAll(io.LimitReader(resp.Body, maxAvatarBytes+1))
	if err != nil {
		return nil, err
	}
	if len(data) > maxAvatarBytes {
		return nil, fmt.Errorf("avatar larger than %d bytes", maxAvatarBytes)
	}
	return data, nil
}

package avatars

import (
	"fmt"
	"io"
	"net/http"
	"net/url"
	"time"
)

const avatarHost = "avatars.example.com"
const maxAvatarBytes = 1 << 20

var client = &http.Client{
	Timeout:       10 * time.Second,
	CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
}

// Fetch downloads the avatar at rawURL, which comes from the user's profile form.
func Fetch(rawURL string) ([]byte, error) {
	u, err := url.Parse(rawURL)
	if err != nil || u.Scheme != "https" || u.Hostname() != avatarHost {
		return nil, fmt.Errorf("avatar URL must be https://%s/...", avatarHost)
	}
	resp, err := client.Get(u.String())
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("avatar fetch: status %d", resp.StatusCode)
	}
	data, err := io.ReadAll(io.LimitReader(resp.Body, maxAvatarBytes+1))
	if err != nil {
		return nil, err
	}
	if len(data) > maxAvatarBytes {
		return nil, fmt.Errorf("avatar larger than %d bytes", maxAvatarBytes)
	}
	return data, nil
}

package cache

import "sync"

type Cache struct {
	mu    sync.Mutex
	items map[string]string
}

// Get returns the cached value for key and whether it was present.
func (c *Cache) Get(key string) (string, bool) {
	c.mu.Lock()
	v, ok := c.items[key]
	if !ok {
		return "", false
	}
	c.mu.Unlock()
	return v, true
}

